ee:message.ee:set-payload:
%dw 2.0
				output application/json
				var customerName = (vars.d365CustomerResponse default [])[0].OrganizationName default "Unknown Name"
				---
				{
					"filterGroups": [
						{
							"filters": [
								{
									"propertyName": "name",
									"operator": "EQ",
									"value": customerName
								}
							]
						}
					],
					"properties": [ "hs_object_id", "name" ]
				}

%dw 2.0
output application/json
var inv = vars.invoice
fun hubSpotCloseDate(d) =
if (d == null) null
else ((("" ++ d) splitBy "T")[0] default null)
---
{
	"properties": {
		"amount": inv.TotalInvoiceAmount as String,
		"closedate": hubSpotCloseDate(inv.InvoiceDate),
		"dealstage": p('hubspot.deal.stage.closedwon'),
		"pipeline": p('hubspot.deal.pipeline.default')
		}
}

%dw 2.0
output application/json
var companyId = vars.hubspotSearchResponse.results[0].id
var inv = vars.invoice
fun hubSpotCloseDate(d) =
	if (d == null) null
	else ((("" ++ d) splitBy "T")[0] default null)
---
{
	"properties": {
		"amount": inv.TotalInvoiceAmount as String,
		"closedate": hubSpotCloseDate(inv.InvoiceDate),
		"dealname": inv.InvoiceNumber as String,
		"dealstage": p('hubspot.deal.stage.closedwon'),
		"pipeline": p('hubspot.deal.pipeline.default')
		},
	"associations": [
		{
			"to": { "id": companyId },
			"types": [
				{
					"associationCategory": "HUBSPOT_DEFINED",
					"associationTypeId": p('hubspot.association.companyToDeal.typeId') as Number
				}
			]
		}
	]
}

%dw 2.0
output application/json
var customerName = (vars.d365CustomerResponse default [])[0].OrganizationName default "Unknown Name"
---
{
	"properties": {
		"name": customerName
	}
}

%dw 2.0
						output application/json
						var companyId = vars.createCompanyResponse.id
						var inv = vars.invoice
						fun hubSpotCloseDate(d) =
							if (d == null) null
							else ((("" ++ d) splitBy "T")[0] default null)
						---
						{
							"properties": {
								"amount": inv.TotalInvoiceAmount as String,
								"closedate": hubSpotCloseDate(inv.InvoiceDate),
								"dealname": inv.InvoiceNumber default "Unknown",
								"dealstage": p('hubspot.deal.stage.closedwon'),
								"pipeline": p('hubspot.deal.pipeline.default')
							},
							"associations": [
								{
									"to": { "id": companyId },
									"types": [
										{
											"associationCategory": "HUBSPOT_DEFINED",
											"associationTypeId": p('hubspot.association.companyToDeal.typeId') as Number
										}
									]
								}
							]
						}
